catalog_script_client.script:
function onLoad() {
    // Portal links can carry a workspace and dates so a user can
    // book straight from a card without retyping. Nothing here
    // runs unless those parameters are present.
    var href = '';
    try {
        href = top.location.href;
    } catch (e) {
        href = window.location.href;   // portal isn't framed
    }

    function param(name) {
        var m = href.match(new RegExp('[?&]' + name + '=([^&#]+)'));
        return m ? decodeURIComponent(m[1].replace(/\+/g, ' ')) : '';
    }

    var wsId    = param('wrm_ws');
    var wsLabel = param('wrm_ws_label');
    var start   = param('wrm_start');
    var end     = param('wrm_end');

    // Reference fields want the sys_id, and the display value
    // too or the field shows the raw id until it resolves.
    if (wsId) {
        g_form.setValue('select_workspace', wsId, wsLabel || '');
    }
    if (start) {
        g_form.setValue('start_date_time', start);
    }
    if (end) {
        g_form.setValue('end_date_time', end);
    }
}
